(3948265, 562303, 15711, '<td valign="top">Excellent blur. I like the title too.  Not sure about the desat - the dog is a touch green. I do like it though. 7</td>', 'Excellent blur. I like the title too.  Not sure about the desat - the dog is a touch green. I do like it though. 7', '2007-07-30 02:06:04.000000', NULL, 1),
(3948266, 560039, 15711, '<td valign="top">What makes this for me are the teeth or lack thereof. LOL</td>', 'What makes this for me are the teeth or lack thereof. LOL', '2007-07-30 02:06:28.000000', NULL, 1),
