(3948275, 562476, 15711, '<td valign="top">I love the perspective and various geometry. Man, I almost missed the guy in the chair. LOL</td>', 'I love the perspective and various geometry. Man, I almost missed the guy in the chair. LOL', '2007-07-30 02:11:50.000000', NULL, 1),
(3948277, 563123, 15711, '<td valign="top">Terrific juxtaposition. Excellent tonal range.</td>', 'Terrific juxtaposition. Excellent tonal range.', '2007-07-30 02:13:01.000000', NULL, 1),
(3948279, 562263, 33379, '<td valign="top">fist photo on the screen and a nice photo to observe.  i like the select dest on the sax and the snazzy suit.</td>', 'fist photo on the screen and a nice photo to observe.  i like the select dest on the sax and the snazzy suit.', '2007-07-30 02:13:29.000000', NULL, 1),
