(3948287, 561839, 33379, '<td valign="top">goo shot, but looks like a lot of neatimage</td>', 'goo shot, but looks like a lot of neatimage', '2007-07-30 02:15:35.000000', NULL, 1),
(3948290, 562565, 66515, '<td valign="top">Focus is quite soft here and I can''t really tell what your camera chose to focus on. A tighter crop may have been more effective so we can see closer look at the heart of the action. Nice well saturated colors and a great capture of the action otherwise however.</td>', 'Focus is quite soft here and I can''t really tell what your camera chose to focus on. A tighter crop may have been more effective so we can see closer look at the heart of the action. Nice well saturated colors and a great capture of the action otherwise however.', '2007-07-30 02:15:50.000000', NULL, 1),
