(3948306, 562878, 48228, '<td valign="top">I love this candid shot very much.....</td>', 'I love this candid shot very much.....', '2007-07-30 02:21:12.000000', NULL, 1),
(3948307, 562848, 66515, '<td valign="top">Nice capture and a very unique subject. Its a shame you lopped off some fingers on his right hand. Selective colorization may have worked well here but I like it just the way it is too.</td>', 'Nice capture and a very unique subject. Its a shame you lopped off some fingers on his right hand. Selective colorization may have worked well here but I like it just the way it is too.', '2007-07-30 02:21:18.000000', NULL, 1),
