(3948388, 562857, 16241, '<td valign="top">lol!</td>', 'lol!', '2007-07-30 02:43:57.000000', NULL, 1),
(3948390, 562625, 6349, '<td valign="top">I don''t know if it is natural or the editing on this but I get a sense that a storm is coming quickly and that this a desperate effort to secure dinner in time.  The perceived tilt of the photo also adds to this drama.</td>', 'I don''t know if it is natural or the editing on this but I get a sense that a storm is coming quickly and that this a desperate effort to secure dinner in time.  The perceived tilt of the photo also adds to this drama.', '2007-07-30 02:44:38.000000', NULL, 1),
(3948392, 563051, 6349, '<td valign="top">Strange, looking at this I am sure I either know that girl or I have also taken a candid photo of her on the street.  Maybe she was a waitress.  Maybe she''s always in the street.  Maybe she''s always rushing like everyone.  Lensbaby?  I''m not even going to comment on the umbrella.  7</td>', 'Strange, looking at this I am sure I either know that girl or I have also taken a candid photo of her on the street.  Maybe she was a waitress.  Maybe she''s always in the street.  Maybe she''s always rushing like everyone.  Lensbaby?  I''m not even going to comment on the umbrella.  7', '2007-07-30 02:46:26.000000', NULL, 1),
(3948393, 562476, 73601, '<td valign="top">dynamite, great lines, conversion, everything very good......adding to fav''s</td>', 'dynamite, great lines, conversion, everything very good......adding to fav''s', '2007-07-30 02:46:28.000000', NULL, 1),
(3948394, 562890, 14476, '<td valign="top">Just a delightful moment you captured.  I''d love to see this cropped closer to the kids.  The sign, grass and architecture take away from the very lovely moment.  Still, it''s a 7 in my book.</td>', 'Just a delightful moment you captured.  I''d love to see this cropped closer to the kids.  The sign, grass and architecture take away from the very lovely moment.  Still, it''s a 7 in my book.', '2007-07-30 02:47:05.000000', NULL, 1),
(3948395, 562878, 11518, '<td valign="top">Great capture!  Works well in B &amp; W and I suspect the original colour version would be pretty interesting too.</td>', 'Great capture!  Works well in B & W and I suspect the original colour version would be pretty interesting too.', '2007-07-30 02:47:09.000000', NULL, 1),
(3948398, 562093, 11518, '<td valign="top">Timeless shot that would work GREAT in B &amp; W or sepia.  Still very nice shot capturing a story.</td>', 'Timeless shot that would work GREAT in B & W or sepia.  Still very nice shot capturing a story.', '2007-07-30 02:49:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3948400, 562360, 6349, '<td valign="top">I like the subject of the photo but think there is a lot that could be improved about the photo itself.  Actually, it''s pretty good how it is, now that I look at it.  If you made it better it would make it less authentic.  This is the kind of quintessentially bad photograph that would show up in some art gallery where people with cheese and wine would chitchat about how technically wonderful it is.</td>', 'I like the subject of the photo but think there is a lot that could be improved about the photo itself.  Actually, it''s pretty good how it is, now that I look at it.  If you made it better it would make it less authentic.  This is the kind of quintessentially bad photograph that would show up in some art gallery where people with cheese and wine would chitchat about how technically wonderful it is.', '2007-07-30 02:49:54.000000', NULL, 1),
(3948401, 562427, 6349, '<td valign="top">woah, people still do that?  nice shot but not exactly saying "street" to me.</td>', 'woah, people still do that?  nice shot but not exactly saying "street" to me.', '2007-07-30 02:50:34.000000', NULL, 1),
(3948402, 563018, 73601, '<td valign="top">would of liked to see more of a blur in the train</td>', 'would of liked to see more of a blur in the train', '2007-07-30 02:51:04.000000', NULL, 1),
(3948404, 562357, 6349, '<td valign="top">great shot but would have been even greater if you waited a second more so the girl on the left was centered in the black part.  That is assuming that the other lady is still looking back at here as that is really what makes the shot work for me.  7</td>', 'great shot but would have been even greater if you waited a second more so the girl on the left was centered in the black part.  That is assuming that the other lady is still looking back at here as that is really what makes the shot work for me.  7', '2007-07-30 02:51:48.000000', NULL, 1),
(3948408, 562751, 35669, '<td valign="top">I cant think of who''s this would be besides Matt.<br/>10 all the way.<br/>Just finished voting and this is just so far beyond anything else in the challenge.</td>', 'I cant think of who''s this would be besides Matt.10 all the way.Just finished voting and this is just so far beyond anything else in the challenge.', '2007-07-30 02:52:27.000000', NULL, 1),
(3948411, 563092, 6349, '<td valign="top">too much neatimage (or some sort of softening) for my tastes.  makes the kid look fake.  Colors are also a bit odd.  I would be curious to see the original of this image as I like the composition and the scene and the lighting (from what I can tell).</td>', 'too much neatimage (or some sort of softening) for my tastes.  makes the kid look fake.  Colors are also a bit odd.  I would be curious to see the original of this image as I like the composition and the scene and the lighting (from what I can tell).', '2007-07-30 02:54:15.000000', NULL, 1),
(3948416, 562971, 33379, '<td valign="top">nice colors</td>', 'nice colors', '2007-07-30 02:56:24.000000', NULL, 1),
(3948421, 562351, 33379, '<td valign="top">this reminds me a video surveillance</td>', 'this reminds me a video surveillance', '2007-07-30 02:58:16.000000', NULL, 1),
(3948428, 561339, 6349, '<td valign="top">some people will tell you that it is disrespectfull and exploitative to take photos of people with disabilities (or homeless people) and I agree with them if the only people you find interesting enough are these types of people.  If, however, you are a photographer, and you enjoy people, in general, and take photos of nearly everybody that you see on the streets, then there is nothing wrong with taking photos of people with disabilites.  Certainly, there is something about the idea of being handicapped that gets an immediate subconscious response from the viewer (either of a photograph or in real life); either they tend to want to look more, or to turn away, and both think they are doing what is right.  Often, people who think taking these photos are exploitative claim to be standing up for the rights of the subjects because they can''t stand up for themselves.  I think that they can.  Maybe the boy can''t stand but he can do the looking that will keep them safe.  I think that these reaction aren''t something we should hide from.</td>', 'some people will tell you that it is disrespectfull and exploitative to take photos of people with disabilities (or homeless people) and I agree with them if the only people you find interesting enough are these types of people.  If, however, you are a photographer, and you enjoy people, in general, and take photos of nearly everybody that you see on the streets, then there is nothing wrong with taking photos of people with disabilites.  Certainly, there is something about the idea of being handicapped that gets an immediate subconscious response from the viewer (either of a photograph or in real life); either they tend to want to look more, or to turn away, and both think they are doing what is right.  Often, people who think taking these photos are exploitative claim to be standing up for the rights of the subjects because they can''t stand up for themselves.  I think that they can.  Maybe the boy can''t stand but he can do the looking that will keep them safe.  I think that these reaction aren''t something we should hide from.', '2007-07-30 03:04:08.000000', NULL, 1),
(3948430, 561144, 6349, '<td valign="top">sweet capture.  perfect shutter speed to render only the fastest of the fast blurry.</td>', 'sweet capture.  perfect shutter speed to render only the fastest of the fast blurry.', '2007-07-30 03:05:08.000000', NULL, 1),
(3948432, 562977, 6349, '<td valign="top">Is this the original Old York?  :)  It''s a bit dark for my taste with not so much going on but it is street.</td>', 'Is this the original Old York?  :)  It''s a bit dark for my taste with not so much going on but it is street.', '2007-07-30 03:06:11.000000', NULL, 1),
(3948437, 562902, 6349, '<td valign="top">nice candid expressions and processing.  7</td>', 'nice candid expressions and processing.  7', '2007-07-30 03:07:19.000000', NULL, 1),
(3948438, 563055, 6349, '<td valign="top">funny.  i''m not a big fan of photos of people taking photos but i do appreciate the humor of this.</td>', 'funny.  i''m not a big fan of photos of people taking photos but i do appreciate the humor of this.', '2007-07-30 03:07:55.000000', NULL, 1),
(3948446, 562763, 6349, '<td valign="top">It''s a great mannequin but to me street photography is all about people.  Real people.  Real people juxtaposed with mannequins is also fantastic and gets people thinking (about what, I don''t know, and it doesn''t really matter what people think as long as they like doing it).  I would like more to think about than "Is that the photographer''s reflection there in the dark next to her leg?"</td>', 'It''s a great mannequin but to me street photography is all about people.  Real people.  Real people juxtaposed with mannequins is also fantastic and gets people thinking (about what, I don''t know, and it doesn''t really matter what people think as long as they like doing it).  I would like more to think about than "Is that the photographer''s reflection there in the dark next to her leg?"', '2007-07-30 03:09:55.000000', NULL, 1),
(3948450, 562476, 6349, '<td valign="top">Shit.  If you''re going to take a photo that reminds me of a photo I took recently but make my photo look ridiculously bad in comparison you should at least give me some sort of warning! 10 and favorite.</td>', 'Shit.  If you''re going to take a photo that reminds me of a photo I took recently but make my photo look ridiculously bad in comparison you should at least give me some sort of warning! 10 and favorite.', '2007-07-30 03:11:21.000000', NULL, 1),
(3948454, 563194, 6349, '<td valign="top">this may be the worst editing i''ve seen in a very long time.  i''m almost even impressed.  stick around dpc, you''ll learn quickly, there are a lot of helpful folks around.</td>', 'this may be the worst editing i''ve seen in a very long time.  i''m almost even impressed.  stick around dpc, you''ll learn quickly, there are a lot of helpful folks around.', '2007-07-30 03:12:40.000000', NULL, 1),
(3948460, 563186, 6349, '<td valign="top">really nice shot and interesting title.  i hate the spelling though.</td>', 'really nice shot and interesting title.  i hate the spelling though.', '2007-07-30 03:13:43.000000', NULL, 1),
(3948462, 563286, 6349, '<td valign="top">wow, this really looks like something out of the past.</td>', 'wow, this really looks like something out of the past.', '2007-07-30 03:14:08.000000', NULL, 1),
(3948476, 562766, 6349, '<td valign="top">very nice capture and editing.  one of those shots that at least to me makes a child look and feel like an adult (but with a little more energy)  maybe you''re right and it''s about not worrying but i actually feel worried about it now...oh look what you''ve done.</td>', 'very nice capture and editing.  one of those shots that at least to me makes a child look and feel like an adult (but with a little more energy)  maybe you''re right and it''s about not worrying but i actually feel worried about it now...oh look what you''ve done.', '2007-07-30 03:17:33.000000', NULL, 1),
(3948480, 562982, 6349, '<td valign="top">haha.  pretty small indeed.</td>', 'haha.  pretty small indeed.', '2007-07-30 03:18:20.000000', NULL, 1),
(3948486, 562150, 16241, '<td valign="top">fawesome edit!!</td>', 'fawesome edit!!', '2007-07-30 03:20:56.000000', NULL, 1),
(3948490, 561848, 6349, '<td valign="top">strange vibe from this one.  don''t know what i''m supposed to think.  the person looks like garlic or a meringue cookie.  i''m hungry.  i like the green shutters.</td>', 'strange vibe from this one.  don''t know what i''m supposed to think.  the person looks like garlic or a meringue cookie.  i''m hungry.  i like the green shutters.', '2007-07-30 03:21:49.000000', NULL, 1),
(3948491, 561805, 6349, '<td valign="top">i like this.  the haphazard composition and tilt give it that authentic street feel.  i don''t know what else to say about it really.</td>', 'i like this.  the haphazard composition and tilt give it that authentic street feel.  i don''t know what else to say about it really.', '2007-07-30 03:22:56.000000', NULL, 1),
(3948494, 562510, 6349, '<td valign="top">way too neatimaged for my tastes and not exactly what i would consider street photography but a good shot otherwise.  full of life and emotion.</td>', 'way too neatimaged for my tastes and not exactly what i would consider street photography but a good shot otherwise.  full of life and emotion.', '2007-07-30 03:23:53.000000', NULL, 1),
