(3948506, 562668, 15711, '<td valign="top">Love the one way sign and the arrow on the ground pointing to them. Nice warm tones for a nice warm sentiment. 8</td>', 'Love the one way sign and the arrow on the ground pointing to them. Nice warm tones for a nice warm sentiment. 8', '2007-07-30 03:30:53.000000', NULL, 1),
