(3948779, 563162, 42198, '<td valign="top">You''ve captured a beautiful expression here. However, I''m distracted by the way the background appears to be masked out.</td>', 'You''ve captured a beautiful expression here. However, I''m distracted by the way the background appears to be masked out.', '2007-07-30 06:06:56.000000', NULL, 1),
(3948780, 562150, 42198, '<td valign="top">Nice post processing.</td>', 'Nice post processing.', '2007-07-30 06:07:48.000000', NULL, 1),
(3948781, 562447, 42198, '<td valign="top">Great use of light/shadow.</td>', 'Great use of light/shadow.', '2007-07-30 06:08:26.000000', NULL, 1),
(3948785, 561548, 42198, '<td valign="top">Lol! Great title! Nice capture as well.</td>', 'Lol! Great title! Nice capture as well.', '2007-07-30 06:10:08.000000', NULL, 1),
(3948787, 563290, 42198, '<td valign="top">This is a great shot. There''s so much to see and interpret in it.</td>', 'This is a great shot. There''s so much to see and interpret in it.', '2007-07-30 06:12:50.000000', NULL, 1),
(3948791, 563097, 42198, '<td valign="top">Interesting composition. But with all the reflections I can''t really tell what''s going on, or what the main subject is supposed to be. Is this on a boat or in a restaurant or through the window of a shop?</td>', 'Interesting composition. But with all the reflections I can''t really tell what''s going on, or what the main subject is supposed to be. Is this on a boat or in a restaurant or through the window of a shop?', '2007-07-30 06:14:32.000000', NULL, 1),
(3948794, 562845, 42198, '<td valign="top">All you needed was someone eating an ice cream to really complete the play on words! :)</td>', 'All you needed was someone eating an ice cream to really complete the play on words! :)', '2007-07-30 06:17:44.000000', NULL, 1),
(3948796, 562427, 42198, '<td valign="top">Nice expression. However, the burning and halo effect around their heads detracts from the shot.</td>', 'Nice expression. However, the burning and halo effect around their heads detracts from the shot.', '2007-07-30 06:19:29.000000', NULL, 1),
(3948835, 561671, 36606, '<td valign="top">brilliant shot</td>', 'brilliant shot', '2007-07-30 07:01:28.000000', NULL, 1),
(3948845, 562476, 58247, '<td valign="top">I love the perspective here as well as the black and white treatment. Good eye!</td>', 'I love the perspective here as well as the black and white treatment. Good eye!', '2007-07-30 07:12:16.000000', NULL, 1),
(3948846, 562857, 58247, '<td valign="top">Ok, this made me laugh...</td>', 'Ok, this made me laugh...', '2007-07-30 07:13:39.000000', NULL, 1),
(3948857, 563293, 58247, '<td valign="top">I would like this shot much more if the column wasn''t there.</td>', 'I would like this shot much more if the column wasn''t there.', '2007-07-30 07:16:51.000000', NULL, 1),
(3948870, 562771, 58247, '<td valign="top">Nice juxtaposition. Good black and white to.</td>', 'Nice juxtaposition. Good black and white to.', '2007-07-30 07:22:59.000000', NULL, 1),
(3948907, 561671, 30982, '<td valign="top">Love the angle and the natural division of the sidewalk from the patterned cobbled street.  The diagonals overhanging add a nice touch as well.</td>', 'Love the angle and the natural division of the sidewalk from the patterned cobbled street.  The diagonals overhanging add a nice touch as well.', '2007-07-30 07:50:02.000000', NULL, 1),
(3948908, 562447, 30982, '<td valign="top">I love the light - and even though she''s centered, the overall composition does not feel that way because of the other elements.  Her feet hanging in the air is a lovely touch.</td>', 'I love the light - and even though she''s centered, the overall composition does not feel that way because of the other elements.  Her feet hanging in the air is a lovely touch.', '2007-07-30 07:51:41.000000', NULL, 1),
(3948910, 561445, 30982, '<td valign="top">Well seen.  One wonders if the person walking away had planned on giving those to someone, but due to circumstances tossed them instead.</td>', 'Well seen.  One wonders if the person walking away had planned on giving those to someone, but due to circumstances tossed them instead.', '2007-07-30 07:54:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3948913, 563186, 30982, '<td valign="top">With your title, I almost expected color.  Clean capture, good conversion.</td>', 'With your title, I almost expected color.  Clean capture, good conversion.', '2007-07-30 07:55:39.000000', NULL, 1),
(3948919, 562586, 30982, '<td valign="top">Good angle for this, though without your title I''d be left wondering what she was up to.</td>', 'Good angle for this, though without your title I''d be left wondering what she was up to.', '2007-07-30 07:58:51.000000', NULL, 1),
(3948925, 562088, 30982, '<td valign="top">A beautiful face - those eyes just reach out and grab!</td>', 'A beautiful face - those eyes just reach out and grab!', '2007-07-30 08:02:55.000000', NULL, 1),
(3948927, 562624, 30982, '<td valign="top">A nice colorful slice of life photograph.</td>', 'A nice colorful slice of life photograph.', '2007-07-30 08:03:45.000000', NULL, 1),
(3948930, 563157, 30982, '<td valign="top">The contrast to me is glamour versus reality.  His downtrodden look emphasizes this well.</td>', 'The contrast to me is glamour versus reality.  His downtrodden look emphasizes this well.', '2007-07-30 08:04:42.000000', NULL, 1),
(3948931, 562429, 30982, '<td valign="top">Nicely captured - a real and engaging record of the event.</td>', 'Nicely captured - a real and engaging record of the event.', '2007-07-30 08:05:28.000000', NULL, 1),
(3948932, 563284, 30982, '<td valign="top">LOL!  Delightful capture!</td>', 'LOL!  Delightful capture!', '2007-07-30 08:05:56.000000', NULL, 1),
(3948936, 563161, 30982, '<td valign="top">A bit of a cheat, shooting from behind (I do it all the time!).  Nice handling of the exposure.</td>', 'A bit of a cheat, shooting from behind (I do it all the time!).  Nice handling of the exposure.', '2007-07-30 08:08:05.000000', NULL, 1),
(3948939, 561265, 30982, '<td valign="top">What a marvelous location for a photo opportunity!  Well seen.</td>', 'What a marvelous location for a photo opportunity!  Well seen.', '2007-07-30 08:08:36.000000', NULL, 1),
(3948940, 562427, 30982, '<td valign="top">Very lovely light and a rich, warm conversion.</td>', 'Very lovely light and a rich, warm conversion.', '2007-07-30 08:09:07.000000', NULL, 1),
(3948949, 560073, 30982, '<td valign="top">Love the old architecture.</td>', 'Love the old architecture.', '2007-07-30 08:14:16.000000', NULL, 1),
(3948951, 562906, 30982, '<td valign="top">Nice use of blur - it does look like he has wings!</td>', 'Nice use of blur - it does look like he has wings!', '2007-07-30 08:14:55.000000', NULL, 1),
(3948953, 561339, 30982, '<td valign="top">Her stance looks tired, a bit weary - a tough burden but one she accepts freely.</td>', 'Her stance looks tired, a bit weary - a tough burden but one she accepts freely.', '2007-07-30 08:16:14.000000', NULL, 1),
(3948954, 562982, 30982, '<td valign="top">Shoulda had the guy remove the car and you''ve got a great pic for the brochure!  Colorful and interesting (to me) but may be a bit posed for the purists.</td>', 'Shoulda had the guy remove the car and you''ve got a great pic for the brochure!  Colorful and interesting (to me) but may be a bit posed for the purists.', '2007-07-30 08:17:21.000000', NULL, 1),
(3948955, 563279, 30982, '<td valign="top">She looks quite lost in her thoughts as she waits.</td>', 'She looks quite lost in her thoughts as she waits.', '2007-07-30 08:18:23.000000', NULL, 1),
(3948958, 562565, 30982, '<td valign="top">Good action shot - lots of interesting faces!</td>', 'Good action shot - lots of interesting faces!', '2007-07-30 08:20:16.000000', NULL, 1),
(3948960, 562372, 30982, '<td valign="top">The area to the right doesn''t seem to be needed - at least not that much of it, as the white cars don''t add to the photograph, in my opinion.</td>', 'The area to the right doesn''t seem to be needed - at least not that much of it, as the white cars don''t add to the photograph, in my opinion.', '2007-07-30 08:21:20.000000', NULL, 1),
(3948972, 563139, 6349, '<td valign="top">Nice.  A top shot in the challenge for sure. 9</td>', 'Nice.  A top shot in the challenge for sure. 9', '2007-07-30 08:29:09.000000', NULL, 1),
(3948976, 562971, 8759, '<td valign="top">Nice crisp capture. Cool bike</td>', 'Nice crisp capture. Cool bike', '2007-07-30 08:31:33.000000', NULL, 1),
(3948995, 562751, 52169, '<td valign="top">Very nice. Love the colors and the look on his face.</td>', 'Very nice. Love the colors and the look on his face.', '2007-07-30 08:44:45.000000', NULL, 1),
(3948999, 563202, 37965, '<td valign="top">Awesome pic, looks a bit pixilated... 7</td>', 'Awesome pic, looks a bit pixilated... 7', '2007-07-30 08:46:01.000000', NULL, 1),
(3949006, 559662, 30982, '<td valign="top">I like the contrast of the flowers - shows a promise of better things to come, perhaps?</td>', 'I like the contrast of the flowers - shows a promise of better things to come, perhaps?', '2007-07-30 08:47:57.000000', NULL, 1),
(3949007, 562652, 52169, '<td valign="top">Thats interesting. 6</td>', 'Thats interesting. 6', '2007-07-30 08:48:01.000000', NULL, 1),
(3949010, 563293, 30982, '<td valign="top">I suspect this may have been set up, in which case you might have moved them just a touch to keep the pole from being between them.  Otherwise, I don''t mind the busy setting - emphasizes that they''re in their own world at the moment.</td>', 'I suspect this may have been set up, in which case you might have moved them just a touch to keep the pole from being between them.  Otherwise, I don''t mind the busy setting - emphasizes that they''re in their own world at the moment.', '2007-07-30 08:50:04.000000', NULL, 1),
(3949015, 563052, 30982, '<td valign="top">A lovely setting and creates a peaceful mood.  I''d kinda like to see the hint of a face.</td>', 'A lovely setting and creates a peaceful mood.  I''d kinda like to see the hint of a face.', '2007-07-30 08:52:36.000000', NULL, 1),
(3949016, 562554, 30982, '<td valign="top">I like the framing by the two blue-jeaned legs.</td>', 'I like the framing by the two blue-jeaned legs.', '2007-07-30 08:53:30.000000', NULL, 1),
(3949017, 562476, 30982, '<td valign="top">Wonderful unique approach.  Has a desolate, lonely feel to it, and I love the geometry.</td>', 'Wonderful unique approach.  Has a desolate, lonely feel to it, and I love the geometry.', '2007-07-30 08:54:27.000000', NULL, 1),
(3949020, 562774, 30982, '<td valign="top">Yep!  Makes me smile - warmth and energy abound!</td>', 'Yep!  Makes me smile - warmth and energy abound!', '2007-07-30 08:55:03.000000', NULL, 1),
(3949024, 562803, 30982, '<td valign="top">It seems to lack a top - it''s nicely, naturally framed on three sides which makes me want a top to it.  Nice reflective look you captured.</td>', 'It seems to lack a top - it''s nicely, naturally framed on three sides which makes me want a top to it.  Nice reflective look you captured.', '2007-07-30 08:56:28.000000', NULL, 1),
(3949029, 562776, 30982, '<td valign="top">An interesting abbreviated shot.  The arches behind beg further exploration.  The way forward looks blocked, yet light beckons indicating that isn''t so.</td>', 'An interesting abbreviated shot.  The arches behind beg further exploration.  The way forward looks blocked, yet light beckons indicating that isn''t so.', '2007-07-30 08:57:59.000000', NULL, 1),
(3949041, 562532, 37965, '<td valign="top">great pic but the tree in the back is distracting... 6</td>', 'great pic but the tree in the back is distracting... 6', '2007-07-30 09:01:48.000000', NULL, 1),
(3949058, 562945, 30982, '<td valign="top">The woman second from the right looks exasperated; the one on the right downright forelorn.  One wonders if their car is broken, leaving them stranded (and captive) here.</td>', 'The woman second from the right looks exasperated; the one on the right downright forelorn.  One wonders if their car is broken, leaving them stranded (and captive) here.', '2007-07-30 09:16:33.000000', NULL, 1),
(3949059, 562766, 30982, '<td valign="top">Lovely!</td>', 'Lovely!', '2007-07-30 09:17:24.000000', NULL, 1),
(3949069, 562976, 30982, '<td valign="top">Great use of a reflection.</td>', 'Great use of a reflection.', '2007-07-30 09:24:37.000000', NULL, 1),
(3949077, 562952, 30982, '<td valign="top">She has a bottle of water in her bra?  Interesting place to keep it!</td>', 'She has a bottle of water in her bra?  Interesting place to keep it!', '2007-07-30 09:27:22.000000', NULL, 1),
(3949078, 563214, 30982, '<td valign="top">Great portrait - would make a nice ad for UnderArmour.</td>', 'Great portrait - would make a nice ad for UnderArmour.', '2007-07-30 09:28:16.000000', NULL, 1),
(3949084, 562252, 30982, '<td valign="top">Love the disembodied feet!  ''Twere me (and I realize it isn''t - just a thought) I''d cut off the signage at the top.</td>', 'Love the disembodied feet!  ''Twere me (and I realize it isn''t - just a thought) I''d cut off the signage at the top.', '2007-07-30 09:31:18.000000', NULL, 1),
(3949104, 563016, 30982, '<td valign="top">Love it!</td>', 'Love it!', '2007-07-30 09:36:56.000000', NULL, 1),
(3949108, 563231, 30982, '<td valign="top">Excellent - presents a wonderful and different image of a summer evening at the ballpark.</td>', 'Excellent - presents a wonderful and different image of a summer evening at the ballpark.', '2007-07-30 09:38:35.000000', NULL, 1),
(3949120, 562857, 11518, '<td valign="top">LMAO!  Very appropriate photo matching the graffitti!  LOL.</td>', 'LMAO!  Very appropriate photo matching the graffitti!  LOL.', '2007-07-30 09:41:08.000000', NULL, 1),
(3949188, 562773, 68573, '<td valign="top">Very well described and nice capture. The expressions on the face are nice and i like that soft toy hanging out there too 8</td>', 'Very well described and nice capture. The expressions on the face are nice and i like that soft toy hanging out there too 8', '2007-07-30 10:12:43.000000', NULL, 1),
(3949206, 561671, 68573, '<td valign="top">Very beautiful image. I like your perspective and the monocrome gorund 8</td>', 'Very beautiful image. I like your perspective and the monocrome gorund 8', '2007-07-30 10:21:19.000000', NULL, 1),
(3949241, 563143, 11920, '<td valign="top">Great image...</td>', 'Great image...', '2007-07-30 10:32:32.000000', NULL, 1),
(3949242, 561839, 11920, '<td valign="top">Love it...</td>', 'Love it...', '2007-07-30 10:33:06.000000', NULL, 1),
(3949245, 562093, 11920, '<td valign="top">Very cool....</td>', 'Very cool....', '2007-07-30 10:34:25.000000', NULL, 1),
