(3950919, 563214, 64929, '<td valign="top">This is no doubt an excellent shot...it just looks way to posed for a "street capture"</td>', 'This is no doubt an excellent shot...it just looks way to posed for a "street capture"', '2007-07-30 18:19:02.000000', NULL, 1),
(3950927, 562202, 20941, '<td valign="top">Magnificent!! A 10</td>', 'Magnificent!! A 10', '2007-07-30 18:21:35.000000', NULL, 1),
(3950941, 563290, 20941, '<td valign="top">Amazing and creative capture of the Gucci ad at Trump Bldg! Luv it!</td>', 'Amazing and creative capture of the Gucci ad at Trump Bldg! Luv it!', '2007-07-30 18:24:36.000000', NULL, 1),
(3950959, 563143, 20941, '<td valign="top">Great capture with awesome presentation! Very cool work!</td>', 'Great capture with awesome presentation! Very cool work!', '2007-07-30 18:31:29.000000', NULL, 1),
(3950963, 562807, 58610, '<td valign="top">Nice sharp focus. Like the dof which emphasizes your subject. Good tonal range from black to white and your border frames it nicely. He looks like he''s expecting someone to join him.</td>', 'Nice sharp focus. Like the dof which emphasizes your subject. Good tonal range from black to white and your border frames it nicely. He looks like he''s expecting someone to join him.', '2007-07-30 18:32:32.000000', NULL, 1),
(3950976, 562363, 58610, '<td valign="top">This very much meets the challenge, so I don''t understand your title at all. Even though your subjects are dark, I like the feeling of the scene. The inclusion of the accordian player adds so much to the sense of motion and flow - like music. Like it.</td>', 'This very much meets the challenge, so I don''t understand your title at all. Even though your subjects are dark, I like the feeling of the scene. The inclusion of the accordian player adds so much to the sense of motion and flow - like music. Like it.', '2007-07-30 18:37:27.000000', NULL, 1),
(3950984, 562804, 20941, '<td valign="top">Awesome!!</td>', 'Awesome!!', '2007-07-30 18:39:13.000000', NULL, 1),
(3951000, 562150, 58610, '<td valign="top">I don''t usually like tone mapping, but i think it adds a lot to this picture. Gives it a bit of a Rockwell painting look. The kid pointing adds to that feeling - something he''d include. I like the subdued color tones as well.</td>', 'I don''t usually like tone mapping, but i think it adds a lot to this picture. Gives it a bit of a Rockwell painting look. The kid pointing adds to that feeling - something he''d include. I like the subdued color tones as well.', '2007-07-30 18:42:17.000000', NULL, 1),
(3951029, 561548, 58610, '<td valign="top">My wife took one look at this and said "that''s ugly". Well, yeah, but it''s also very poignant - we''re all heading for this someday...    I find the kid sitting behind them distracting, and the girls expression is rather odd, but this is a candid format and you can''t have everything just the way you want it, can you?</td>', 'My wife took one look at this and said "that''s ugly". Well, yeah, but it''s also very poignant - we''re all heading for this someday...    I find the kid sitting behind them distracting, and the girls expression is rather odd, but this is a candid format and you can''t have everything just the way you want it, can you?', '2007-07-30 18:50:11.000000', NULL, 1),
(3951049, 563164, 58610, '<td valign="top">I like the bright colors of the phone booth juxtaposed with the somber background of the alley. I wished you''d been able to capture someone using the phone, or walking in the alley. That would have added to the "street photography" feeling.</td>', 'I like the bright colors of the phone booth juxtaposed with the somber background of the alley. I wished you''d been able to capture someone using the phone, or walking in the alley. That would have added to the "street photography" feeling.', '2007-07-30 18:58:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3951064, 562758, 58610, '<td valign="top">OK, I stared for probably 15 secs before I got your title. I guess I''m tired. In any case, this has a very candid/documetary feel to it. Even though she is aware of your presence, she is wary and curious of your intentions.</td>', 'OK, I stared for probably 15 secs before I got your title. I guess I''m tired. In any case, this has a very candid/documetary feel to it. Even though she is aware of your presence, she is wary and curious of your intentions.', '2007-07-30 19:04:11.000000', NULL, 1),
(3951065, 561578, 60805, '<td valign="top">very candid! good capture 8</td>', 'very candid! good capture 8', '2007-07-30 19:04:12.000000', NULL, 1),
(3951067, 561874, 78599, '<td valign="top">Wow the ceiling would have been awesome in the rhythm contest!</td>', 'Wow the ceiling would have been awesome in the rhythm contest!', '2007-07-30 19:05:18.000000', NULL, 1),
(3951068, 562766, 78599, '<td valign="top">Hehe íslendingur:P</td>', 'Hehe íslendingur:P', '2007-07-30 19:05:49.000000', NULL, 1),
(3951075, 562360, 78599, '<td valign="top">Hehe I like the idea. The photo leaves a bit to be desired though...slightly overexposed and out of focus...</td>', 'Hehe I like the idea. The photo leaves a bit to be desired though...slightly overexposed and out of focus...', '2007-07-30 19:09:03.000000', NULL, 1),
(3951078, 561956, 12268, '<td valign="top">Hello There! I love the title to this shot, very cute &amp; creative. The grain is a bit distracting tho it follows the creative flow of the pic, i think. Good luck!</td>', 'Hello There! I love the title to this shot, very cute & creative. The grain is a bit distracting tho it follows the creative flow of the pic, i think. Good luck!', '2007-07-30 19:09:42.000000', NULL, 1),
(3951079, 563139, 58610, '<td valign="top">This looks like it hurts to me. Great capture. Interestingly, because of the dof and the motion of the dancer, the only thing sharply in focus are his arms -  the pivotal point within his dance. Even though they''re fuzzy, we can see the audiences'' faces and their apprectiation of this fellows efforts. Nicely done.</td>', 'This looks like it hurts to me. Great capture. Interestingly, because of the dof and the motion of the dancer, the only thing sharply in focus are his arms -  the pivotal point within his dance. Even though they''re fuzzy, we can see the audiences'' faces and their apprectiation of this fellows efforts. Nicely done.', '2007-07-30 19:09:53.000000', NULL, 1),
(3951080, 562771, 60805, '<td valign="top">9</td>', '9', '2007-07-30 19:10:34.000000', NULL, 1),
(3951081, 562252, 12268, '<td valign="top">Very nice. I love the blur of the moving folks, especially that the foot of each seems to stand still. Nice capture</td>', 'Very nice. I love the blur of the moving folks, especially that the foot of each seems to stand still. Nice capture', '2007-07-30 19:10:35.000000', NULL, 1),
(3951082, 562890, 12268, '<td valign="top">Nice shot! Seems to be set up tho but who cares. I like it! 8</td>', 'Nice shot! Seems to be set up tho but who cares. I like it! 8', '2007-07-30 19:11:20.000000', NULL, 1),
(3951083, 561866, 12268, '<td valign="top">quite intersting, IMO. I like that you choose to broaden the scope of the challenge and not shoot some random folks on the street. Love that the pigeon is backlit with the symmetrical shadow. Is that a bit of burnin'' around the corners? Seems uneven. Will vote as if it is not tho since it is not overly evident. Awesome shot &amp; good luck! 8</td>', 'quite intersting, IMO. I like that you choose to broaden the scope of the challenge and not shoot some random folks on the street. Love that the pigeon is backlit with the symmetrical shadow. Is that a bit of burnin'' around the corners? Seems uneven. Will vote as if it is not tho since it is not overly evident. Awesome shot & good luck! 8', '2007-07-30 19:13:15.000000', NULL, 1),
(3951086, 562384, 78599, '<td valign="top">hehe weird:P</td>', 'hehe weird:P', '2007-07-30 19:13:47.000000', NULL, 1),
(3951087, 562532, 12268, '<td valign="top">There is a nice subtle contrast in expressions here. Quite cativating. Good stuff! 9</td>', 'There is a nice subtle contrast in expressions here. Quite cativating. Good stuff! 9', '2007-07-30 19:13:57.000000', NULL, 1),
(3951089, 562890, 78599, '<td valign="top">I know its out of your control, but I think it would have been better if they were all stepping evenly:P</td>', 'I know its out of your control, but I think it would have been better if they were all stepping evenly:P', '2007-07-30 19:14:37.000000', NULL, 1),
(3951090, 562897, 12268, '<td valign="top">Great title. The shot seems a bit dull on my monitor tho. Think it could use a bump in contrast. Good luck!</td>', 'Great title. The shot seems a bit dull on my monitor tho. Think it could use a bump in contrast. Good luck!', '2007-07-30 19:14:50.000000', NULL, 1),
(3951094, 561332, 58610, '<td valign="top">I quit smoking over 9 years ago so my first reaction is always ''yuk'' when I see someone smoking. The large area behind the subject without any detail is somewhat disconcerting at first, and I find myself wondering if you did that on purpose, although it would appear not. On the other had, more detail would only distract from the main idea, so I think it actually works better this way. Brighter highlights - perhaps in the flowers - would help balance it overall.</td>', 'I quit smoking over 9 years ago so my first reaction is always ''yuk'' when I see someone smoking. The large area behind the subject without any detail is somewhat disconcerting at first, and I find myself wondering if you did that on purpose, although it would appear not. On the other had, more detail would only distract from the main idea, so I think it actually works better this way. Brighter highlights - perhaps in the flowers - would help balance it overall.', '2007-07-30 19:17:59.000000', NULL, 1),
(3951099, 563157, 52439, '<td valign="top">This is the best in the challenge.<br/>Straight 10.<br/>It''s his pose, all about his pose.</td>', 'This is the best in the challenge.Straight 10.It''s his pose, all about his pose.', '2007-07-30 19:21:06.000000', NULL, 1),
(3951100, 562652, 52439, '<td valign="top">Came back togive it the 10 it deserves.<br/>Absolutely brilliant.</td>', 'Came back togive it the 10 it deserves.Absolutely brilliant.', '2007-07-30 19:21:10.000000', NULL, 1),
(3951101, 563003, 52439, '<td valign="top">Simple, sharp, great layout within the frame.<br/>9.</td>', 'Simple, sharp, great layout within the frame.9.', '2007-07-30 19:21:43.000000', NULL, 1),
(3951107, 562214, 58610, '<td valign="top">Well, he didn''t listen, did he? I would have liked to have gotten a sense of what it was they were doing here. Can''t tell from the subjects (except that he appears to be looking off into the distance at something) and there are no clues in the background. Is she taking her own picture, or a picture of whatever is in front of them?</td>', 'Well, he didn''t listen, did he? I would have liked to have gotten a sense of what it was they were doing here. Can''t tell from the subjects (except that he appears to be looking off into the distance at something) and there are no clues in the background. Is she taking her own picture, or a picture of whatever is in front of them?', '2007-07-30 19:24:02.000000', NULL, 1),
(3951113, 559551, 58610, '<td valign="top">Well balanced subject, sharply focused with a clear story.</td>', 'Well balanced subject, sharply focused with a clear story.', '2007-07-30 19:28:39.000000', NULL, 1),
(3951121, 562847, 58610, '<td valign="top">My only suggestion is more detail in the shadows. I like the compostion and the story you''ve captured.</td>', 'My only suggestion is more detail in the shadows. I like the compostion and the story you''ve captured.', '2007-07-30 19:30:45.000000', NULL, 1),
(3951129, 562556, 60657, '<td valign="top">Made me smile too. Very nice (8)</td>', 'Made me smile too. Very nice (8)', '2007-07-30 19:33:23.000000', NULL, 1),
(3951132, 563143, 60657, '<td valign="top">Very nice, a bit under-exposed but a difficult shot at low-light conditions.</td>', 'Very nice, a bit under-exposed but a difficult shot at low-light conditions.', '2007-07-30 19:34:18.000000', NULL, 1),
(3951135, 563293, 60657, '<td valign="top">Nice contrast and composition. Liked the title too :-)</td>', 'Nice contrast and composition. Liked the title too :-)', '2007-07-30 19:35:34.000000', NULL, 1),
(3951137, 562066, 60657, '<td valign="top">Ah! brings back memories... nicely captured.</td>', 'Ah! brings back memories... nicely captured.', '2007-07-30 19:36:38.000000', NULL, 1),
(3951141, 562429, 60657, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2007-07-30 19:38:18.000000', NULL, 1),
(3951144, 563164, 60657, '<td valign="top">The deserted street and neglected walls add to the effect. Well done.</td>', 'The deserted street and neglected walls add to the effect. Well done.', '2007-07-30 19:39:49.000000', NULL, 1),
(3951145, 563202, 60657, '<td valign="top">Would have loved to see the ending. Nice!</td>', 'Would have loved to see the ending. Nice!', '2007-07-30 19:40:42.000000', NULL, 1),
(3951154, 561020, 60657, '<td valign="top">Very nicely done. A great depiction.</td>', 'Very nicely done. A great depiction.', '2007-07-30 19:43:33.000000', NULL, 1),
