(3951177, 561265, 60657, '<td valign="top">Amen</td>', 'Amen', '2007-07-30 19:50:45.000000', NULL, 1),
(3951183, 562945, 60657, '<td valign="top">Every family has at least one :-) Nice, although, would have liked to see more of the upper half.</td>', 'Every family has at least one :-) Nice, although, would have liked to see more of the upper half.', '2007-07-30 19:52:26.000000', NULL, 1),
(3951186, 561856, 60657, '<td valign="top">Nice!</td>', 'Nice!', '2007-07-30 19:53:02.000000', NULL, 1),
(3951192, 562977, 79630, '<td valign="top">Really nice image, contrast between the dark pavement and the ligt building works well.</td>', 'Really nice image, contrast between the dark pavement and the ligt building works well.', '2007-07-30 19:55:15.000000', NULL, 1),
(3951206, 563161, 51802, '<td valign="top">I think this would have been much better if you had captured them from the front.  Their facial expressions as they were talking would have made this shot.</td>', 'I think this would have been much better if you had captured them from the front.  Their facial expressions as they were talking would have made this shot.', '2007-07-30 20:02:49.000000', NULL, 1),
(3951210, 563055, 51802, '<td valign="top">I really like how you captured the girl taking the picture.  That is a nice little surprise in this shot.</td>', 'I really like how you captured the girl taking the picture.  That is a nice little surprise in this shot.', '2007-07-30 20:04:19.000000', NULL, 1),
(3951215, 562606, 51802, '<td valign="top">I love the mood here.</td>', 'I love the mood here.', '2007-07-30 20:04:38.000000', NULL, 1),
(3951216, 562616, 51802, '<td valign="top">That is a wonderful smile!</td>', 'That is a wonderful smile!', '2007-07-30 20:05:04.000000', NULL, 1),
(3951220, 562793, 51802, '<td valign="top">I think this is exactly what this challenge is about!  Great story here.</td>', 'I think this is exactly what this challenge is about!  Great story here.', '2007-07-30 20:06:12.000000', NULL, 1),
(3951223, 561874, 51802, '<td valign="top">The B&amp;W works great here.  I love the pattern of the ceiling and the light from it.</td>', 'The B&W works great here.  I love the pattern of the ceiling and the light from it.', '2007-07-30 20:06:59.000000', NULL, 1),
(3951226, 561149, 51802, '<td valign="top">What a cool place!  The lighting is wonderful.</td>', 'What a cool place!  The lighting is wonderful.', '2007-07-30 20:08:02.000000', NULL, 1),
(3951249, 561144, 68035, '<td valign="top">An absoutely amzing shot which i feel has got to be destined for a ribbon.  The motion blur of the kickers legs is stunning and I cant help feeling that he is so committed to making the shot that he is going to do a bicycle kick and end up smacking his back on the floor<br/> <br/>I love streets being reclaimed for sports<br/> <br/>Brilliant B&amp;W conversion as well.  I scored this originally as a nine but just had to come back to bump to a ten<br/> <br/>Amazing</td>', 'An absoutely amzing shot which i feel has got to be destined for a ribbon.  The motion blur of the kickers legs is stunning and I cant help feeling that he is so committed to making the shot that he is going to do a bicycle kick and end up smacking his back on the floor I love streets being reclaimed for sports Brilliant B&W conversion as well.  I scored this originally as a nine but just had to come back to bump to a ten Amazing', '2007-07-30 20:17:44.000000', NULL, 1),
