(3967340, 562804, 2158, '<td valign="top">I haven''t finished voting yet, but this is my favourite so far.  Good luck.</td>', 'I haven''t finished voting yet, but this is my favourite so far.  Good luck.', '2007-08-03 23:54:49.000000', NULL, 1),
(3967443, 562751, 58728, '<td valign="top">There are so many interesting things going on in this photo.  I especially love the birds above the chimney. And the colors, the composition...it''s wonderful.  10.</td>', 'There are so many interesting things going on in this photo.  I especially love the birds above the chimney. And the colors, the composition...it''s wonderful.  10.', '2007-08-04 00:29:05.000000', NULL, 1),
(3967445, 562476, 58728, '<td valign="top">This is my pick to ribbon.  I love it.  This picture is perfect.</td>', 'This is my pick to ribbon.  I love it.  This picture is perfect.', '2007-08-04 00:29:09.000000', NULL, 1),
(3967446, 562710, 58728, '<td valign="top">Love it.  The processing is really awesome.  Great street scene.</td>', 'Love it.  The processing is really awesome.  Great street scene.', '2007-08-04 00:29:30.000000', NULL, 1),
(3967447, 562906, 58728, '<td valign="top">10.  This is great.  LOVE the blur.</td>', '10.  This is great.  LOVE the blur.', '2007-08-04 00:29:43.000000', NULL, 1),
(3967453, 562766, 58728, '<td valign="top">10 all the way!  What a fun capture.  LOVE the b&amp;w choice.  The comp is great, and I''m getting such a great sense of adventure.</td>', '10 all the way!  What a fun capture.  LOVE the b&w choice.  The comp is great, and I''m getting such a great sense of adventure.', '2007-08-04 00:30:21.000000', NULL, 1),
(3967542, 562963, 34462, '<td valign="top">what an interesting perspective on this guy.</td>', 'what an interesting perspective on this guy.', '2007-08-04 00:59:38.000000', NULL, 1),
(3967543, 563256, 51802, '<td valign="top">A faster shutter speed would have prevented the blur and the overexposure.</td>', 'A faster shutter speed would have prevented the blur and the overexposure.', '2007-08-04 01:03:57.000000', NULL, 1),
(3967547, 562861, 51802, '<td valign="top">The crooked horizon makes this seem like a snap shot.</td>', 'The crooked horizon makes this seem like a snap shot.', '2007-08-04 01:06:49.000000', NULL, 1),
(3967548, 562351, 51802, '<td valign="top">This is just a little too random of a composition.  Also, there is nothing that really holds the viewer''s interest.</td>', 'This is just a little too random of a composition.  Also, there is nothing that really holds the viewer''s interest.', '2007-08-04 01:08:13.000000', NULL, 1),
