(3967801, 562953, 62357, '<td valign="top">I like this shot, but do find the car a little distracting.</td>', 'I like this shot, but do find the car a little distracting.', '2007-08-04 05:43:32.000000', NULL, 1),
(3967863, 563272, 62187, '<td valign="top">As a photo, it looks very nice - for the challenge - nothing is saying ''Street'' to me.</td>', 'As a photo, it looks very nice - for the challenge - nothing is saying ''Street'' to me.', '2007-08-04 06:58:35.000000', NULL, 1),
