(4026012, 562257, 61651, '<td valign="top">Rich, glowing colors, nice geometry, the hints of people, and that surreal inclusion of a man in a flying machine make this such a fascinating shot.</td>', 'Rich, glowing colors, nice geometry, the hints of people, and that surreal inclusion of a man in a flying machine make this such a fascinating shot.', '2007-08-24 12:26:41.000000', NULL, 0),
